pub fn apply_all(values: &[u32], transform: impl Fn(u32) -> u32) -> Vec<u32> {
    values.iter().map(|value| transform(*value)).collect()
}

pub fn retry<F: FnMut() -> bool>(mut attempt: F, max: usize) -> bool {
    for _ in 0..max {
        if attempt() {
            return true;
        }
    }
    false
}

fn main() {
    let bump = 10;
    let bumped = apply_all(&[1, 2, 3], |value| value + bump);
    println!("{bumped:?}");

    let mut count = 0;
    let ok = retry(|| {
        count += 1;
        count == 2
    }, 3);
    println!("{ok} after {count} tries");
}

