use std::sync::mpsc;
use std::thread;

pub fn sum_with_channel(values: Vec<u32>) -> u32 {
    let (tx, rx) = mpsc::channel();

    thread::spawn(move || {
        for value in values {
            tx.send(value).unwrap();
        }
    });

    // rx.iter() ends when the sender is dropped.
    rx.iter().sum()
}

fn main() {
    println!("{}", sum_with_channel(vec![10, 20, 30]));
}

